    private function readSnippetAsset(ServerRequestInterface $request): SnippetAssetCreateParams
    {
        $this->logDebug("Read entity for Snippet asset");
        $span = $this->startSpan("Read entity for Snippet asset");
        try {
            $parsed = $request->getParsedBody() ?? [];
            $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
            $errorsList = new ConstraintFailList();
            $value = new SnippetAssetCreateParams();
            $valueUid = SnippetAssetUidVO::tryFrom($body['uid'] ?? null, $errorsList);
            if (null !== $valueUid) {
                $value->uid($valueUid);
            }
            if (in_array('snippet', array_keys($body))) {
                $valueSnippet = SnippetAssetSnippetVO::tryFrom(isset($body['snippet']['$ref']) ? new SnippetRef($body['snippet']['$ref']) : null, $errorsList);
                if (null !== $valueSnippet) {
                    $value->snippet($valueSnippet);
                }
            }
            $valueCode = SnippetAssetCodeVO::tryFrom($body['code'] ?? null, $errorsList);
            if (null !== $valueCode) {
                $value->code($valueCode);
            }
            $valueType = SnippetAssetTypeVO::tryFrom($body['type'] ?? null, $errorsList);
            if (null !== $valueType) {
                $value->type($valueType);
            }
            $content = $body['content'] ?? null;
            $preffixContent = $this->context->getBaseUrl() . '/api/document/snippet-asset/-/temp-content?temp=';
            if (null !== $content && strpos($content, $preffixContent) === 0) {
                $valueContent = SnippetAssetContentVO::tryFromTemporal(base64_decode(substr($content, strlen($preffixContent))), $errorsList);
                if (null !== $valueContent) {
                    $value->content($valueContent);
                }
            }
            $value->version(SnippetAssetVersionVO::tryFrom($body['version'] ?? null, $errorsList));
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
